from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrow_date': date, 'due_date': date, 'returned': bool}
        self.users = {}  # user -> {'current_book': book_id, 'fines': float, 'borrow_history': [(book_id, borrow_date, return_date, fine)]}

    def add_book(self, book_id: str) -> None:
        if book_id not in self.books:
            self.books[book_id] = {
                'borrowed_by': None,
                'borrow_date': None,
                'due_date': None,
                'returned': True
            }

    def borrow(self, user: str, book_id: str, day: date) -> None:
        # Check if book exists
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        # Check if book is already borrowed
        if not self.books[book_id]['returned']:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already holds a book
        if user in self.users and self.users[user]['fines'] > 0:
            if self.users[user]['current_book'] is not None:
                raise ValueError(f"User {user} already holds a book and has unpaid fines")

        # Calculate due date (loan_days business days from borrow day)
        due_date = self._calculate_due_date(day, self.loan_days)

        # Update book status
        self.books[book_id] = {
            'borrowed_by': user,
            'borrow_date': day,
            'due_date': due_date,
            'returned': False
        }

        # Update user status
        if user not in self.users:
            self.users[user] = {
                'current_book': book_id,
                'fines': 0.0,
                'borrow_history': []
            }
        else:
            self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        # Check if book exists
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        # Check if book is currently borrowed by this user
        if self.books[book_id]['borrowed_by'] != user or self.books[book_id]['returned']:
            raise ValueError(f"Book {book_id} is not currently borrowed by user {user}")

        # Calculate fine
        fine = 0.0
        if day > self.books[book_id]['due_date']:
            delay_days = self._count_business_days(self.books[book_id]['due_date'] + timedelta(days=1), day)
            fine = delay_days * self.daily_fine

        # Update book status
        self.books[book_id]['returned'] = True

        # Update user status
        if user in self.users:
            self.users[user]['current_book'] = None
            self.users[user]['fines'] += fine
            self.users[user]['borrow_history'].append((
                book_id, 
                self.books[book_id]['borrow_date'], 
                day, 
                fine
            ))

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user]['fines']

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['fines'] = 0.0

    def _calculate_due_date(self, start_date: date, loan_days: int) -> date:
        """Calculate due date by adding loan_days business days to start_date"""
        current_date = start_date
        days_added = 0

        while days_added < loan_days:
            current_date += timedelta(days=1)
            # Skip weekends (Saturday=5, Sunday=6)
            if current_date.weekday() < 5:  # Monday=0, Friday=4
                days_added += 1

        return current_date

    def _count_business_days(self, start_date: date, end_date: date) -> int:
        """Count business days (Mon-Fri) between start_date (inclusive) and end_date (inclusive)"""
        if start_date > end_date:
            return 0

        count = 0
        current = start_date
        while current <= end_date:
            if current.weekday() < 5:  # Monday=0, Friday=4
                count += 1
            current += timedelta(days=1)

        return count
